import { useEffect, useState } from "react";
import { getAreas, predictTraffic, getSignal } from "./api";

function App() {
  const [areas, setAreas] = useState([]);

  useEffect(() => {
    getAreas()
      .then(setAreas)
      .catch(console.error);
  }, []);

  const handlePredict = async () => {
    const result = await predictTraffic({
      area: "Hazratganj",
      hour: 10,
      day_of_week: 2,
      is_holiday: 0,
      weather: "Clear",
      temperature: 30,
      vehicle_count: 180,
      num_lanes: 4,
    });

    console.log(result);
  };

  const handleSignal = async () => {
    const result = await getSignal({
      queue_n: 20,
      queue_s: 10,
      queue_e: 15,
      queue_w: 8,
      waiting: 35,
    });

    console.log(result);
  };

  return (
    <div>
      <h1>Smart Traffic Optimization</h1>

      <button onClick={handlePredict}>Predict Traffic</button>

      <button onClick={handleSignal}>Get Signal</button>

      <ul>
        {areas.map((area, index) => (
          <li key={index}>{area.area}</li>
        ))}
      </ul>
    </div>
  );
}

export default App;
